const D = { energy:.55, scale:1, hue:200, dots:.6, facets:.5, sparkle:.6, cord:.5, x:.5, y:.28, speed:1, density:.5, style:'silver', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext,TAU=Math.PI*2;
const u=Math.min(W,H), R=u*0.10*P.scale, cx=P.x*W, cy=P.y*H;
const spin=t*(0.4+en*0.9)*P.speed;
const kick=K.pulse*0.4+A.bass*0.5;
function dotHue(i){ if(sty==='colorful') return (i*53+t*20)%360; if(sty==='gold') return 45; if(sty==='holo') return (i*37+t*40)%360; if(sty==='chrome') return 200; return P.hue; }
const dsat = sty==='silver'?15 : sty==='chrome'?18 : 80;

// ---- light dots sweeping the room (additive, large area — the motion driver)
dc.save(); blendMode(ADD);
const nd=Math.floor(12+P.dots*60);
for(let i=0;i<nd;i++){ const a=fr(i)*TAU + spin*(fr(i+5)>0.5?1:-1)*1.2; const rad=(0.15+fr(i+3)*0.9);
  const px=cx + Math.cos(a)*W*0.55*rad; const py=cy + R*1.4 + Math.sin(a*1.3+i)*H*0.35*rad + rad*H*0.2;
  const tw=0.4+0.6*Math.sin(t*(2+fr(i)*4)+i*3);
  const sz=(3+fr(i+9)*9)*(0.6+P.sparkle)*(0.8+kick*0.6);
  fill(color(dotHue(i), dsat, 100, (18+tw*45)*P.alpha/100));
  rect(px-sz/2,py-sz/2,sz,sz);   // square light specks
}
blendMode(BLEND); dc.restore();

// ---- cord
if(P.cord>0.05){ stroke(color(0,0,60,60*P.alpha/100)); strokeWeight(2); line(cx,0,cx,cy-R); noStroke(); }

// ---- the ball (grid of mirror facets)
push(); translate(cx,cy);
noStroke(); fill(color(P.hue,dsat,22,90*P.alpha/100)); circle(0,0,R*2+4); // dark base sphere
const rows=Math.floor(7+P.facets*9);
for(let r=0;r<rows;r++){ const lat=(r/(rows-1)-0.5)*Math.PI; const y=Math.sin(lat)*R; const rr=Math.cos(lat)*R; const cols=Math.max(4,Math.floor(rows*Math.cos(lat)*1.6));
  for(let cI=0;cI<cols;cI++){ const lon=cI/cols*TAU + spin; const x=Math.cos(lon)*rr; const z=Math.sin(lon)*rr;
    if(z<-2) continue;  // back faces hidden
    const facelight = Math.max(0, Math.cos(lon-0.6)) ; // lit toward upper-left
    const shimmer=0.5+0.5*Math.sin(t*3+r*1.3+cI*0.7);
    const br = 30 + facelight*55 + shimmer*20*(0.5+P.sparkle);
    const fh = sty==='colorful'||sty==='holo' ? (lon*57+t*20)%360 : P.hue;
    const fs = sty==='silver'?10 : sty==='gold'?45 : sty==='chrome'?12 : 55;
    fill(color(fh,fs,Math.min(100,br), P.alpha));
    const fw=rr*TAU/cols*0.92, fhh=R*Math.PI/rows*0.92;
    rect(x-fw/2, y-fhh/2, fw*(0.5+z/R*0.5+0.5), fhh); // perspective-ish squash
  }
}
// specular hotspot
fill(color(0,0,100, 60*P.alpha/100)); dc.save(); dc.shadowBlur=18; dc.shadowColor=color(P.hue,20,100).toString(); circle(-R*0.35,-R*0.35, R*0.5); dc.restore();
noStroke();
pop();
blendMode(BLEND); dc.shadowBlur=0;
